      "rank": 1,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Harald Rose",
        "Maximilian Haider",
        "Ondrej L. Krivanek"
      ],
      "assessment": {
        "nobel_worthiness": "Aberration correction overcame a fundamental limit in electron optics and made atomic-scale imaging and spectroscopy broadly possible. This is a major, durable invention that opened new experimental access to matter.",
        "attribution": "Rose's optical theory and the experimental correctors developed by Haider and Krivanek represent complementary, pivotal contributions. The history should distinguish the early corrector work from later practical instruments.",
        "maturity": "The impact is established across decades of use in materials science, chemistry, and physics, with clear experimental confirmation.",
        "uncertainties": [
          "The boundaries of credit among the corrector pioneers and other contributors to early aberration-corrected instruments need careful historical review."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Kenneth J. Schafer",
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision model gave strong-field physics a clear physical picture and enabled high-harmonic generation as a route to attosecond science. It connected an important theoretical insight to experimentally accessible electron dynamics.",
        "attribution": "The named theorists and experimentalist made complementary contributions to formulating and establishing the three-step account. The original papers and sequence of independent developments matter for allocating credit.",
        "maturity": "The model has been tested extensively and underpins a mature field of ultrafast measurement.",
        "uncertainties": [
          "The field's foundations include several closely timed theoretical and experimental contributions beyond this compact credited group."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "The titanium-sapphire laser and reliable passive mode-locking made femtosecond pulses practical and transformed ultrafast optical science. It is a consequential invention with broad and lasting experimental use.",
        "attribution": "Moulton's laser medium and the distinct Kerr-lens and semiconductor saturable-absorber mode-locking advances are all represented. The award's scope should distinguish these related but separate innovations.",
        "maturity": "The technology has been validated and used for decades, and its influence on ultrafast science is settled.",
        "uncertainties": [
          "Credit for the laser system and for the separate mode-locking techniques does not map perfectly onto one unified discovery."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase revealed that quantum phase and geometry have observable consequences, shaping broad areas of modern physics. These are deep conceptual discoveries with enduring experimental relevance.",
        "attribution": "Aharonov's effect and Berry's general geometric phase are related but distinct contributions; the credited pairing captures two central advances while the prize scope must remain precise.",
        "maturity": "The phenomena have been confirmed in many physical settings and are established foundations of quantum mechanics.",
        "uncertainties": [
          "A single prize framing risks conflating distinct discoveries separated in time and conceptual scope."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Rashid Sunyaev"
      ],
      "assessment": {
        "nobel_worthiness": "The Sunyaev-Zel'dovich effects gave cosmologists a powerful way to study hot plasma and the growth of large-scale structure, with lasting observational importance.",
        "attribution": "Sunyaev is a central theorist named here, but the effect was developed jointly with Yakov Zel'dovich, who is absent from the credited names. That omission makes attribution on this ballot incomplete.",
        "maturity": "The effects are firmly established through extensive observations and remain useful in current cosmology.",
        "uncertainties": [
          "The listed credit excludes Zel'dovich, a co-originator whose contribution is essential to fair attribution."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Heino Falcke",
        "James M. Moran",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale imaging provided a striking and technically extraordinary test of black-hole physics, demonstrating what global very-long-baseline interferometry can resolve.",
        "attribution": "The named scientists represent important theoretical, observational, and instrument leadership. The result depended on a large international collaboration, so credit must be grounded in specific original contributions rather than visibility alone.",
        "maturity": "The image and subsequent observations are robust, although the scientific interpretation continues to develop.",
        "uncertainties": [
          "It is difficult to represent the full collaboration's contributions within the prize's small laureate limit."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Qi-Kun Xue",
        "Xi Dai",
        "Zhong Fang"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum anomalous Hall effect established a remarkable topological transport state without an external magnetic field and opened a significant experimental direction in quantum materials.",
        "attribution": "The ballot joins theoretical prediction and experimental realization. The exact division between prediction, material preparation, and decisive transport measurements needs close examination.",
        "maturity": "The effect has been reproduced and extended, though practical devices and the broader material landscape remain active research areas.",
        "uncertainties": [
          "The nominated trio may not capture all of the experimental contributors to the first convincing observation."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that coherent quantum computation can in principle withstand physical noise, a foundational result with substantial influence on quantum information physics.",
        "attribution": "Kitaev, Steane, and Shor are central to distinct theoretical advances in codes and fault tolerance. Their individual contributions should be matched carefully to the prize's stated scope.",
        "maturity": "The theory is well established, while large-scale fault-tolerant quantum computation remains an ongoing experimental challenge.",
        "uncertainties": [
          "The proposed scope bundles several related advances and may omit other foundational contributors."
        ]
      }
    }
  ]
